  [458312] = { "$D1の間、受けるすべてのダメージを$N1%減少させます。一度守られると、$D2の間はDivine Shield、Divine Protection、Blessing of Protectionの対象にならなくなります。", "受けるダメージが$N1%減少します。", 0x4f4c8473, 0xa4f10210, "uu" },
