  [458371] = { "$D1の間、受けるすべてのダメージを$N1%減少させます。一度守られると、$D2の間はDivine Shield、Divine Protection、Blessing of Protectionの対象にならなくなります。", "受けるダメージが$N1%減少します。", 0x4f4c8473, 0xa4f10210, "uu" },
  [458393] = { "Mongoose Biteが、近接攻撃のたびに$N1%の確率で発動するようになり、敵が回避したときは100%の確率で発動します。この確率は累積し、リセットされなければ攻撃のたびに$N3%ずつ上昇します。さらにMongoose Biteは、Attack Powerの$N4%に等しい追加ダメージを与えます。", nil, 0x31863f78, nil, "um" },
  [458403] = { nil, "すべての攻撃の命中率が$N1%上昇します。", nil, 0x36a319d2, "mu" },
  [458407] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [458436] = { "武器ダメージの$N1%を与える猛烈な一撃を放ち、対象を$D1かけて$N2のPhysicalダメージを受けるBleed状態にします。", "$N2秒ごとに$N1のBleedダメージを受けます。", 0xa0da7bd7, 0xd7a9220a, "uu" },
  [458454] = { "残響を捧げます。", nil, 0x10968b43, nil, "um" },
  [458479] = { "Wyvern StingのアビリティをWyvern Strikeに置き換えます。Wyvern Strikeは武器ダメージの$N1%を与える猛烈な一撃で、対象をBleed状態にして継続ダメージを与えます。\n\nWyvern Strikeを使うにはWyvern Stingのタレントが必要で、Survivalの呪文書にあるWyvern Stingのアビリティと置き換わります。", nil, 0xdd66b74c, nil, "um" },
  [458481] = { "武器ダメージの$N1%を与える猛烈な一撃を放ち、対象を$D1かけて$N2のPhysicalダメージを受けるBleed状態にします。", "$N2秒ごとに$N1のBleedダメージを受けます。", 0xa0da7bd7, 0xd7a9220a, "uu" },
  [458482] = { "武器ダメージの$N1%を与える猛烈な一撃を放ち、対象を$D1かけて$N2のPhysicalダメージを受けるBleed状態にします。", "$N2秒ごとに$N1のBleedダメージを受けます。", 0xa0da7bd7, 0xd7a9220a, "uu" },
