  [458820] = { nil, "目標は$N2秒ごとに$N1のNatureダメージを受け、受けるArcane、Fire、Frost、Nature、Shadowのダメージが$N3%増加します。", nil, 0x4290b92c, "mu" },
  [458821] = { "武器に30分間持続する毒を塗ります。攻撃のたびに$N2%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与え、敵が受けるArcane、Fire、Frost、Nature、Shadowのダメージを$N5%増加させます。1体の対象に最大$N6回までスタックします。\n\nOccult PoisonはDeadly Poisonとして扱われ、Deadly Poisonで発動する、またはDeadly Poisonを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xac6b5ded, nil, "um" },
  [458822] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに30%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与え、敵が受けるArcane、Fire、Frost、Nature、Shadowのダメージを$N5%増加させます。1体の対象に最大$N6回までスタックします。\n\nOccult PoisonはDeadly Poisonとして扱われ、Deadly Poisonで発動する、またはDeadly Poisonを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xdba5bb61, nil, "um" },
  [458841] = { nil, "Hydraxianが最大限の救済をもたらしており、Molten Core内の熱を最小限に抑えています。", nil, 0x19674aed, "mu" },
  [458842] = { nil, "Hydraxianがもたらす救済は限られています。Molten Coreはほとんど耐えがたいほど暑くなっています。", nil, 0x9a755df5, "mu" },
  [458843] = { nil, "Hydraxianは救済をもたらしていません。Molten Coreの熱は最も激しい状態です。", nil, 0x17d3b2a6, "mu" },
  [458856] = { "友好的な対象を$N1回復します。対象への過剰回復の$N2%は、$D1持続する吸収シールドに変換されます。Divine Lightを複数回唱えても、このシールドは累積しません。\n\nDivine LightはHoly Lightで発動する、またはHoly Lightを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0x5eb11dfb, nil, "um" },
  [458857] = { nil, "$N1のダメージを吸収します。", nil, 0xbd35a1c1, "mu" },
